<?php
require __DIR__.'/private/bootstrap.php';
if(installed()){header('Location: index.php');exit;}
$error='';$lock=null;$created=array();$connection=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        csrf_check($_POST['csrf'] ?? '');
        if(PHP_VERSION_ID<70000||!extension_loaded('pdo_mysql'))fail('PHP 7.0+ and PDO MySQL are required.');
        $host=text_value($_POST,'host',150);if(!preg_match('/^[a-zA-Z0-9.:-]+$/',$host))fail('Invalid database host.');
        $database=text_value($_POST,'database',100);if(!preg_match('/^[a-zA-Z0-9_$-]+$/',$database))fail('Use the database name supplied by your host.');
        $port=(int)($_POST['port'] ?? 3306);if($port<1||$port>65535)fail('Invalid MySQL port.');
        $username=text_value($_POST,'username',100);$password=isset($_POST['dbpassword'])?(string)$_POST['dbpassword']:'';
        $name=text_value($_POST,'name',100);$email=email_value($_POST['email'] ?? '');$ownerPassword=password_value($_POST['password'] ?? '');
        $config=array('host'=>$host,'port'=>$port,'database'=>$database,'username'=>$username,'password'=>$password,'key'=>bin2hex(random_bytes(32)));
        $lock=fopen(__DIR__.'/private/install.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))fail('Another setup is running. Please wait and reload.');
        if(installed())fail('Already installed. Open index.php.');
        $connection=db_connect($config);
        $check=$connection->query("SHOW TABLES LIKE 'lifeos\\_%'")->fetchAll();if($check)fail('This database already contains LifeOS tables. Use a fresh database or restore the original configuration. No tables were changed.');
        $schema=require __DIR__.'/private/schema.php';
        foreach($schema as $table=>$sql){$connection->exec($sql);$created[]='lifeos_'.$table;}
        $connection->beginTransaction();
        $connection->exec('INSERT INTO lifeos_meta(id,revision) VALUES(1,1)');
        $stmt=$connection->prepare('INSERT INTO lifeos_users(name,email,password,created_at) VALUES(?,?,?,UTC_TIMESTAMP())');$stmt->execute(array($name,$email,password_hash($ownerPassword,PASSWORD_DEFAULT)));$uid=$connection->lastInsertId();
        $stmt=$connection->prepare('INSERT INTO lifeos_boards(name,owner_id,created_at) VALUES(?,?,UTC_TIMESTAMP())');$stmt->execute(array('Life, in motion',$uid));$bid=$connection->lastInsertId();
        $stmt=$connection->prepare('INSERT INTO lifeos_members(board_id,user_id,role) VALUES(?,?,?)');$stmt->execute(array($bid,$uid,'owner'));
        $stmt=$connection->prepare('INSERT INTO lifeos_columns(board_id,id,name,position,is_done) VALUES(?,?,?,?,?)');$position=0;foreach(array('todo'=>'To do','progress'=>'In progress','review'=>'In review','done'=>'Done') as $key=>$title)$stmt->execute(array($bid,$key,$title,$position++,$key==='done'?1:0));
        $connection->commit();
        $path=config_path();$handle=@fopen($path,'x');if(!$handle)fail('Cannot write configuration. Allow PHP to write to the private folder, then retry.');
        $contents="<?php\n// Generated by setup. Keep this file private.\nreturn ".var_export($config,true).";\n";
        $written=fwrite($handle,$contents);fclose($handle);if($written!==strlen($contents)){@unlink($path);fail('Configuration could not be written. Check available disk space.');}@chmod($path,0600);
        $created=array();sign_in(array('id'=>$uid,'session_version'=>1));header('Location: index.php');exit;
    }catch(Throwable $e){
        if($connection&&$connection->inTransaction())$connection->rollBack();
        if($connection&&$created){foreach(array_reverse($created) as $table){try{$connection->exec('DROP TABLE '.$table);}catch(Throwable $ignored){}}}
        $error=$e instanceof LifeError?$e->getMessage():'Could not connect or create tables. Verify the database host, name, user, password, and that the user has table privileges.';
        if(!($e instanceof LifeError))error_log('LifeOS setup: '.$e->getMessage());
    }
    if(is_resource($lock)){flock($lock,LOCK_UN);fclose($lock);}
}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function previous($key,$default=''){return h(isset($_POST[$key])?$_POST[$key]:$default);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up LifeOS</title><link rel="stylesheet" href="auth.css"></head><body><main class="auth-card setup-card"><a class="auth-brand" href="index.php">◈ LifeOS</a><h1>Your workspace, ready in one step.</h1><p>Enter your hosting database details and choose your owner account. LifeOS creates its tables and configuration automatically.</p><?php if($error):?><div role="alert" class="error"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><fieldset><legend>MySQL database</legend><div class="fields"><label>Database name<input name="database" required value="<?=previous('database')?>" autocomplete="off"></label><label>Database username<input name="username" required value="<?=previous('username')?>" autocomplete="off"></label></div><label>Database password<input name="dbpassword" type="password" autocomplete="new-password"></label><details><summary>Connection settings · default localhost:3306</summary><div class="fields"><label>Host<input name="host" value="<?=previous('host','localhost')?>" required></label><label>Port<input name="port" type="number" min="1" max="65535" value="<?=previous('port','3306')?>" required></label></div></details></fieldset><fieldset><legend>Your owner account</legend><div class="fields"><label>Your name<input name="name" required maxlength="100" autocomplete="name" value="<?=previous('name')?>"></label><label>Email<input name="email" type="email" required autocomplete="email" value="<?=previous('email')?>"></label></div><label>Password<input name="password" type="password" minlength="10" maxlength="72" required autocomplete="new-password"><small>At least 10 characters.</small></label></fieldset><button>Install & open my workspace →</button></form><p class="fine-print">Create the database and assign its user in cPanel first. Setup needs no Composer, build tools, cron jobs, or database import. Existing tables are never replaced. Setup locks automatically after installation.</p></main></body></html>
